#!/usr/bin/env python3
"""Generate dockerman templates from the reviewed Nocturne v0.2.7 release."""
import json,re,shlex,xml.etree.ElementTree as E
from pathlib import Path
ROOT=Path(__file__).resolve().parent
TEMPLATES=ROOT.parent/'templates'
TEMPLATES.mkdir(exist_ok=True)
source=json.loads((ROOT/'upstream/release-compose.json').read_text())
items=[('nocturne-postgres-server','postgres:17-bookworm','01-nocturne-postgres.xml'),('nocturne-api','ghcr.io/nightscout/nocturne/nocturne-api:0.2.7','02-nocturne-api.xml'),('nocturne-web','ghcr.io/nightscout/nocturne/nocturne-web:0.2.7','03-nocturne-web.xml'),('gateway','mcr.microsoft.com/dotnet/nightly/yarp:2.3-preview','04-nocturne-gateway.xml')]
secret_names={'INSTANCE_KEY','POSTGRES_PASSWORD','POSTGRES_APP_PASSWORD','POSTGRES_MIGRATOR_PASSWORD','POSTGRES_WEB_PASSWORD'}
for service,image,filename in items:
 name='nocturne-gateway' if service=='gateway' else service
 env=source['services'][service]['environment'].copy()
 env.pop('SCALAR_CUSTOM_CSS',None)
 for k,v in list(env.items()):
  env[k]=re.sub(r'\$\{([^}]+)\}',lambda m:'@'+m[1]+'@' if m[1] in secret_names|{'BASE_DOMAIN'} else ({'OTEL_EXPORTER_OTLP_PROTOCOL':'grpc','POSTGRES_USERNAME':'nocturne'}.get(m[1],'')),v)
 env.update({'ASPNETCORE_ENVIRONMENT':'Production'} if service=='nocturne-api' else {})
 # Separate files keep credentials outside XML templates and allow the GUI to recreate containers.
 (ROOT/'config'/f'{name}.env.in').write_text('\n'.join(k+'='+v for k,v in env.items())+'\n')
 c=E.Element('Container',version='2')
 def field(k,v=''):E.SubElement(c,k).text=v
 field('Name',name);field('Repository',image);field('Registry','https://github.com/nightscout/nocturne/pkgs/container/nocturne%2Fnocturne-api' if service=='nocturne-api' else 'https://github.com/nightscout/nocturne')
 field('Network','nocturne');field('MyIP');field('Shell','sh');field('Privileged','false')
 field('Project','https://github.com/nightscout/nocturne');field('Support','https://github.com/kevlacross/unraid-templates/issues')
 descriptions={
 'nocturne-postgres-server':'Step 1 of 4: dedicated PostgreSQL 17 database for Nocturne. Run prepare.sh first to generate credentials and bootstrap files. Install all four templates on the nocturne custom network. Database initialization runs only on an empty data directory. Do not reuse a Nightscout MongoDB directory.',
 'nocturne-api':'Step 2 of 4: Nocturne 0.2.7 API. Requires the Nocturne PostgreSQL template, prepared environment files and the nocturne custom network. Start after PostgreSQL is ready. Credentials and role-specific connection strings are in the private appdata environment file.',
 'nocturne-web':'Step 3 of 4: Nocturne 0.2.7 web interface. Requires the Nocturne API and PostgreSQL templates. Use the gateway over HTTPS through your reverse proxy; direct web access bypasses required routing.',
 'gateway':'Step 4 of 4: Nocturne routing gateway. Requires all other Nocturne templates and files generated by prepare.sh. Point your existing HTTPS reverse proxy at Unraid port 1612 and preserve Host, X-Forwarded-Host and X-Forwarded-Proto. No bundled Watchtower or Docker socket access. Community packaging, not an official Nocturne product.'}
 field('Overview',descriptions[service]);field('Category','Tools:Utilities');field('WebUI','https://@BASE_DOMAIN@' if service in ('gateway','nocturne-web') else '')
 field('Icon','https://raw.githubusercontent.com/nightscout/nocturne/v0.2.7/src/Web/packages/app/static/favicon.png');field('TemplateURL',f'https://raw.githubusercontent.com/kevlacross/unraid-templates/main/templates/{filename}')
 field('ReadMe','https://github.com/kevlacross/unraid-templates/blob/main/nocturne/README.md')
 field('Requires','Run nocturne/prepare.sh before installation. Requires all four Nocturne containers, a custom Docker network named nocturne, generated private environment files and an HTTPS reverse proxy. See ReadMe.')
 field('License','AGPL-3.0-or-later')
 extra=f'--restart=unless-stopped --log-opt max-size=10m --log-opt max-file=3 --env-file=@APPDATA@/{name}.env'
 if service=='gateway':extra+=' --entrypoint=dotnet'
 field('ExtraParams',extra);field('PostArgs','/app/yarp.dll' if service=='gateway' else '')
 def config(name,target,default,mode,typ,desc):
  E.SubElement(c,'Config',Name=name,Target=target,Default=default,Mode=mode,Description=desc,Type=typ,Display='always',Required='true',Mask='false').text=default
 if service=='nocturne-postgres-server':
  config('Database storage','/var/lib/postgresql/data','@APPDATA@/postgres','rw','Path','Dedicated persistent PostgreSQL 17 data. Back up before version changes.')
  config('Database bootstrap','/docker-entrypoint-initdb.d/00-init.sh','@APPDATA@/00-init.sh','ro','Path','Generated by prepare.sh; this is a file, not a directory.')
 if service in ('nocturne-api','nocturne-web'):
  config('Public hostname','BASE_DOMAIN','@BASE_DOMAIN@','','Variable','Hostname only, without protocol or path. Must match both API and Web and your HTTPS proxy.')
 if service=='gateway':config('HTTP gateway port','5000','1612','tcp','Port','Forward your HTTPS reverse proxy to this port. Keep API, web and PostgreSQL private.')
 E.indent(c,space='  ');E.ElementTree(c).write(TEMPLATES/filename,encoding='utf-8',xml_declaration=True)
# Native docker commands are generated from the same XML fields as dockerman uses.
lines=['#!/usr/bin/env bash','set -euo pipefail','cd -- "$(dirname -- "$0")"','docker network inspect nocturne >/dev/null 2>&1 || docker network create nocturne >/dev/null']
for service,image,filename in items:
 c=E.parse(TEMPLATES/filename).getroot();name=c.findtext('Name')
 a=['docker','run','-d','--name',name,'--network','nocturne','--label','net.unraid.docker.managed=dockerman','--label','net.unraid.docker.webui=https://@BASE_DOMAIN@']+shlex.split(c.findtext('ExtraParams'))
 for cf in c.findall('Config'):
  if cf.get('Type')=='Path':a+=['-v',cf.text+':'+cf.get('Target')+':'+cf.get('Mode')]
  elif cf.get('Type')=='Port':a+=['-p',cf.text+':'+cf.get('Target')]
  elif cf.get('Type')=='Variable':a+=['-e',cf.get('Target')+'='+cf.text]
 a+=[image]+shlex.split(c.findtext('PostArgs') or '')
 lines += [f'if docker container inspect {name} >/dev/null 2>&1; then',f'  docker start {name} >/dev/null','else','  '+shlex.join(a),'fi']
 if service=='nocturne-postgres-server':
  lines += ['for attempt in {1..180}; do',"  if docker exec nocturne-postgres-server sh -c 'PGPASSWORD=\"$POSTGRES_PASSWORD\" psql -h 127.0.0.1 -U \"$POSTGRES_USER\" -d nocturne -tAc \"SELECT 1 FROM pg_roles WHERE rolname = '\"'\"'nocturne_app'\"'\"'\"' 2>/dev/null | grep -qx '1'; then break; fi",'  if [[ "$attempt" == 180 ]]; then echo "PostgreSQL bootstrap did not become ready" >&2; exit 1; fi','  sleep 2','done']
(ROOT/'start.sh.in').write_text('\n'.join(lines)+'\n')

# Public CA templates use usable default paths; prepare.sh fills the selected host settings.
for path in TEMPLATES.glob("0*-nocturne-*.xml"):
 path.write_text(path.read_text().replace("@APPDATA@","/mnt/user/appdata/nocturne").replace("@BASE_DOMAIN@","nocturne.example.com"))
